/* Explicit first connection; revision checks prevent silent cross-device overwrite. */
(()=>{'use strict';const bridge=window.studyBackupBridge;if(!bridge)return;let revision=null,last='',connected=false,busy=false,timer,conflict=false;const button=document.createElement('button');button.textContent='☁️ 다른 기기와 이어서 공부';document.querySelector('#study-device-bar').append(button);const dialog=document.createElement('dialog');dialog.className='study-dialog';dialog.setAttribute('aria-label','기기 간 공부 기록 연결');document.body.append(dialog);
async function api(data){const r=await fetch('/api/study',{cache:'no-store',method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const v=await r.json();if(!r.ok){const e=Error(v.error||'연결하지 못했어.');e.status=r.status;throw e}return v}
function snap(){const b=bridge.snapshot();return {core:b.core,extra:b.extra}}
function fingerprint(p){const copy=JSON.parse(JSON.stringify(p));delete copy.core.timer;return JSON.stringify(copy)}
function inspect(p){return bridge.inspect(JSON.stringify({app:'future-compass-study',version:1,createdAt:new Date().toISOString(),...p}))}
function summary(p){const b=inspect(p);return `시간표 ${b.core.table.flat().filter(Boolean).length}교시 · 할 일 ${b.core.tasks.length}개 · 시험·과제 ${b.core.dates.length}개 · 복습 ${b.core.reviews.length}개`}
function showError(e){connected=false;button.textContent='☁️ 연결 확인하기';notice(e.message+' 기기 기록은 그대로야.')}
async function push(){if(!connected||busy||conflict||document.hidden)return;const p=snap(),f=fingerprint(p);if(f===last)return;busy=true;button.textContent='☁️ 저장 중…';try{const v=await api({revision,payload:p});revision=v.revision;last=f;button.textContent='☁️ 서버에 저장됨'}catch(e){if(e.status===409){conflict=true;connected=false;button.textContent='☁️ 다른 기기 기록 확인';notice('다른 기기에서 바꾼 기록이 있어. 연결 버튼을 눌러 비교해줘.')}else showError(e)}finally{busy=false}}
function connect(saved){connected=true;conflict=false;last=fingerprint(saved||snap());button.textContent='☁️ 이어서 공부 연결됨';clearInterval(timer);timer=setInterval(push,3000)}
button.onclick=async()=>{if(busy)return;busy=true;button.disabled=true;try{const remote=await api();revision=remote.revision;const local=snap();if(remote.payload)inspect(remote.payload);dialog.innerHTML='<button class="dialog-close" aria-label="닫기">×</button><h2>☁️ 다른 기기에서도 이어서</h2><p>시간표·할 일·시험·복습·질문 기록을 연결해요. 연결 후 바꾼 기록은 서버에 자동 저장돼요.</p><p id="local-summary"></p><p id="remote-summary"></p><div class="actions"><button id="use-local" class="primary">이 기기 기록을 서버에 저장</button>'+ (remote.payload?'<button id="use-cloud">서버 기록을 이 기기로 가져오기</button>':'')+'</div><p class="muted">두 기록을 자동으로 합치지 않아요. 불러오기 전 기기 기록은 저장 도움말에서 복원 취소할 수 있어요. 진로 탐색 기록은 별도예요.</p>';dialog.querySelector('#local-summary').textContent='이 기기: '+summary(local);dialog.querySelector('#remote-summary').textContent=remote.payload?'서버: '+summary(remote.payload)+' · '+new Date(remote.updated*1000).toLocaleString('ko-KR'):'서버에 아직 공부 기록이 없어요.';dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.showModal();dialog.querySelector('#use-local').onclick=async()=>{if(busy)return;if(remote.payload&&!confirm('서버 기록을 현재 기기 기록으로 바꿀까요? 다른 기기의 자료를 먼저 확인해 주세요.'))return;busy=true;try{const p=snap();const v=await api({revision,payload:p});revision=v.revision;connect(p);dialog.close();notice('연결했어. 이 화면에서 바꾸는 공부 기록을 서버에 저장할게.')}catch(e){showError(e);dialog.close()}finally{busy=false}};const cloud=dialog.querySelector('#use-cloud');if(cloud)cloud.onclick=async()=>{if(busy)return;busy=true;try{const fresh=await api();if(fresh.revision!==revision)throw Error('서버 기록이 방금 바뀌었어. 다시 비교해줘.');bridge.apply(inspect(fresh.payload));connect();dialog.close();notice('서버 기록을 불러왔어. 타이머는 멈춘 상태야.')}catch(e){showError(e)}finally{busy=false}}}catch(e){showError(e)}finally{busy=false;button.disabled=false}};
// Push on normal edits, and poll for newer records without replacing unsaved work.
setInterval(async()=>{if(!connected||busy||document.hidden)return;busy=true;try{const remote=await api();if(remote.revision!==revision){connected=false;conflict=true;button.textContent='☁️ 다른 기기 기록 확인';notice('다른 기기에서 바꾼 기록이 있어. 연결 버튼에서 가져올 기록을 골라줘.')}}catch(e){showError(e)}finally{busy=false}},30000);
window.addEventListener('beforeunload',e=>{if(connected&&fingerprint(snap())!==last){e.preventDefault();e.returnValue=''}});
})();
